use vstd::prelude::*;

verus! {
fn copy<T: Copy>(a: &Vec<T>) -> (result: Vec<T>)
    ensures
        result.len() == a.len(),
        forall|i: usize| (i < a.len() ==> result[i] == a[i]),
        // input vector a is not modified
        a.len() == old(a.len()),
    decreases
        0,
{
    let mut res: Vec<T> = Vec::empty();
    let mut i: usize = 0;
    while i < a.len()
        invariant
            i <= a.len(),
            res.len() == i,
            forall|j: usize| (j < i ==> res[j] == a[j]),
            a.len() == old(a.len()),
        decreases
            a.len() - i,
    {
        res.push(a[i]);
        i = i + 1;
    }
    res
}
}

